// presti-reponse-seule : la fenêtre du passage. Un passage par minute ; une demande n'est lue que 30 s après sa création (le temps
// que le chemin codé écrive son motif), dans une fenêtre d'une minute alignée sur l'horloge : chaque demande tombe dans UNE fenêtre
// et une seule (n8n n'écrit pas en base : l'unicité tient aux fenêtres, pas à un registre). Copie figée contrôlée par
// scripts/reponse-seule-n8n-qa.mjs ; l'instant vient de Date.now() (le juge le fixe).
const PASSAGE_MS = 60000;
const DECALAGE_MS = 30000;
const DOUBLONS_MS = 86400000;
const RAFALE_MS = 600000;
const maintenant = Date.now();
const passage = Math.floor(maintenant / PASSAGE_MS) * PASSAGE_MS;
const fin = passage - DECALAGE_MS;
const debut = fin - PASSAGE_MS;
const decalageParis = (t) => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Paris', hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).formatToParts(new Date(t))) p[x.type] = Number(x.value);
  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - Math.floor(t / 1000) * 1000;
};
const jour = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(fin));
const [a, m, j] = jour.split('-').map(Number);
const minuit0 = Date.UTC(a, m - 1, j);
const minuit = minuit0 - decalageParis(minuit0 - 7200000);
const depuisJour = Math.min(minuit, debut);
return [{ json: { jour, debut: new Date(debut).toISOString(), fin: new Date(fin).toISOString(), depuis_jour: new Date(depuisJour).toISOString(), depuis_doublons: new Date(fin - DOUBLONS_MS).toISOString(), depuis_rafale: new Date(debut - RAFALE_MS).toISOString(), passage: new Date(passage).toISOString(), simulation: true } }];

// presti-reponse-seule : la DÉCISION de la réponse qui part seule, refaite depuis app/api/leads/route.ts:283-320 (pause, plafond par artisan,
// puis decisionReponse de lib/plateformeConfig.ts:216-229 : main prise, modeEffectif, mot d'escalade de l'artisan, sujets d'escalade de
// lib/pilote/regles.ts, limite de messages, plage horaire). Code pur : rien n'est envoyé, rien n'est écrit, aucun modèle n'est appelé.
// Les listes de mots et les expressions viennent de lib/pilote/regles.ts par exporter.mjs (jamais retapées) ; copie figée contrôlée par
// scripts/reponse-seule-n8n-qa.mjs, qui rejoue la vraie fonction sur un corpus de messages.
const MOTS_TOUJOURS = ["litige","litigieux","sinistre","avocat","menace","mise en demeure","en demeure","plainte","tribunal","tribunaux","huissier","contentieux","conteste","contestation","arnaque","escroquerie","escroc","urgence","fuite","dégât des eaux","dégâts des eaux","dégât d’eau","dégâts d’eau","inondation","inondé","assurance","justice","prud’hom","juridique","médiateur","conciliat","dgccrf","gendarme","préjudice","indemni","dédommag","réclamation","lettre recommandée","recommandé avec","en recommandé","accusé de réception","vice caché","vices cachés","opposition","malfaçon","décennale","expert","dégât","incendie","brûl","blessé","blessure","électrocut","monoxyde","intoxi","effondr","écroul","infiltr","court-circuit","court circuit","danger","eau partout","est tombé","est tombée","sont tombés","une chute","fait une chute","paierai pas","payerai pas","réglerai pas","paie pas","paye pas","pas payer cette","pas payer la","pas payer tant","refuse de payer","refuse de régler","rembours","avis négatif","mauvais avis","mauvaise pub","assureur","menaç","voleur","poursuiv","vous attaquer","paierai rien","payerai rien","pas un centime","bloque le paiement","retiens le solde","retenir le solde","une étoile","explos","étincel","ça fume","pris une décharge","décharge électrique","s’est coupé","s’est blessé","signalement","réclame","remise en état","conflit","dénonce","fui","fuy","perd de l’eau","perdent de l’eau","perte d’eau","urgen","urgemment","goutte","suinte","déborde","sous l’eau","de l’eau par terre","plus de chauffage","plus d’eau chaude","au plus vite","pressant","entendre parler de moi","retiens le paiement","rendez-moi mon argent","une honte","avis sur google","plombs ont sauté","pris feu","court-jus","coule du","ça coule","goutte du","escroqu","plaindre","plains","dommages et","consommateur","bâcl","mal fait","fraude","disjoncteur saute","ça disjoncte","disjoncte sans","refui","refuy","humidit","humide","eau coule","coule le long","ruissel","s’échapp","s’écoul","eau qui sort","eau sort","eau se perd","de l’eau sous","lâche de l’eau","crache de l’eau","pisse de l’eau","se vide tout seul","perd du liquide","perte de liquide","c’est pressé","est très pressé","suis pressé","odeur"];
const MOTS_ENTIERS = ["gaz","procès","police","accident","accidents","pompiers","juge","ufc","vol","samu","urssaf"];
const FAUSSE_URGENCE = / (?:pas d|sans|aucune|rien d) urgen[a-z]*| pas urgent[a-z]*| (?:sans|aucun|pas de) degats?| une chute de (?:neige|pluie|grele|feuilles)/g;
const PERTE_D_EAU = / (?:perd[a-z]*|pert|pertes?)(?: (?!chauffe )[a-z0-9]+){0,5}? (?:d |de l |de |l |d l )?d?l?eaux? /;
const APPAREIL_PERD = / (?:chauffe eau|ballon|cumulus|radiateur|radiateurs|robinet|chaudiere|tuyau|tuyaux|joint|wc|evier|lavabo|siphon|vanne) (?:perd|perdent|perdait|perdaient|a perdu|ont perdu)(?= $| pouvez| pourriez| depuis| encore| toujours| beaucoup| un peu| pas mal| partout| de partout| par terre| par le| sous| a nouveau| merci)/;
const NOMS_NEUTRES = /\b(?:chaudieres?|cuisinieres?|plaques?(?:[^a-z0-9]+de[^a-z0-9]+cuisson)?)[^a-z0-9]+(?:(?:a|au)[^a-z0-9]+)?gaz\b|\bbruleurs?\b|\battestations?[^a-z0-9]+(?:d[^a-z0-9]+)?(?:assurances?[^a-z0-9]*)?(?:decennale|rc pro|responsabilite civile)?/g;
const PLANS_AUTO = ["signature","entreprise","business"];
const MAX_PAR_ARTISAN = 8;
const RAFALE_MS = 600000;
const DEFAUT = { mode_reponse: 'assistee', auto_24_7: true, auto_debut: null, auto_fin: null, escalade_mots: ["urgence","fuite","degat des eaux","inondation","gaz","assurance"], limite_messages: 8 };
const fen = $('Fenetre du passage').first().json;
const lire = (nom) => $(nom).all().map((i) => i.json).filter((x) => x && typeof x === 'object' && typeof x.id === 'string');
const ordre = (a, b) => (a.created_at < b.created_at ? -1 : a.created_at > b.created_at ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
const texte = (v) => (typeof v === 'string' ? v : '');
const sansAccents = (s) => texte(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const enMots = (s) => ' ' + sansAccents(s).replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const RACINES_TOUJOURS = MOTS_TOUJOURS.map((m) => [m, enMots(m).trim()]);
const RACINES_ENTIERES = MOTS_ENTIERS.map((m) => [m, enMots(m).trim()]);
// lib/pilote/regles.ts : sujetEscalade (les sujets qu'aucun réglage ne retire, puis les mots de l'artisan).
const sujetEscalade = (messages, motsArtisan) => {
  const artisan = (Array.isArray(motsArtisan) ? motsArtisan : []).filter((m) => typeof m === 'string').map((m) => [m, sansAccents(m).trim()]).filter(([, k]) => k !== '');
  for (const brut of messages) {
    if (typeof brut !== 'string' || !brut.trim()) continue;
    const mots = enMots(brut).replace(NOMS_NEUTRES, ' ').replace(FAUSSE_URGENCE, ' ').replace(/ {2,}/g, ' ');
    for (const [m, k] of RACINES_TOUJOURS) if (k && mots.includes(' ' + k)) return m;
    for (const [m, k] of RACINES_ENTIERES) if (k && mots.includes(' ' + k + ' ')) return m;
    if (PERTE_D_EAU.test(mots)) return 'perte d’eau';
    if (APPAREIL_PERD.test(mots)) return 'perte d’eau';
    if (mots.includes(' ca sent ')) return 'ça sent';
    const brutSansNoms = sansAccents(brut).replace(NOMS_NEUTRES, ' ');
    for (const [m, k] of artisan) if (brutSansNoms.includes(k)) return m;
  }
  return null;
};
// lib/plateformeConfig.ts : motEscalade, heureFrance, dansLaPlage.
const motEscalade = (cfg, message) => {
  const n = sansAccents(message);
  for (const m of cfg.escalade_mots || []) { const k = sansAccents(m); if (k && n.includes(k)) return m; }
  return null;
};
const heureFrance = (d) => {
  try { return parseInt(new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', hour12: false }).format(d), 10); } catch (e) { return d.getUTCHours(); }
};
const dansLaPlage = (cfg, maintenant) => {
  if (cfg.auto_24_7 !== false) return true;
  const d = cfg.auto_debut, f = cfg.auto_fin;
  if (d == null || f == null) return true;
  const h = heureFrance(maintenant);
  return d <= f ? h >= d && h < f : h >= d || h < f;
};
const comptes = {};
lire('Lire comptes').forEach((c) => { comptes[c.id] = c; });
const reglages = {};
$('Lire reglages').all().map((i) => i.json).filter((x) => x && typeof x.artisan_id === 'string').forEach((r) => { reglages[r.artisan_id] = r; });
const rafale = lire('Lire rafale').sort(ordre);
const sortie = [];
const rendre = (lead, decision, motif, extra) => sortie.push({ json: { courrier: 'decision', lead_id: lead.id, decision, motif, mot: null, simulation: true, ...extra } });
for (const lead of lire('Lire demandes').sort(ordre)) {
  if (!(lead.created_at >= fen.debut && lead.created_at < fen.fin)) continue;
  const artisan = comptes[lead.artisan_id];
  if (!artisan) { sortie.push({ json: { courrier: 'ignore', lead_id: lead.id, raison: 'compte introuvable', simulation: true } }); continue; }
  // app/api/leads/route.ts:285 : la pause de l'artisan passe avant tout.
  if (artisan.leads_pause === true) { rendre(lead, 'refus', 'pause'); continue; }
  // app/api/leads/route.ts:296 : au plus huit demandes par artisan et par fenêtre de dix minutes (les suivantes sont gardées, sans réponse).
  const dansLaRafale = rafale.filter((r) => r.artisan_id === lead.artisan_id && r.created_at <= lead.created_at && Date.parse(r.created_at) > Date.parse(lead.created_at) - RAFALE_MS);
  const rang = dansLaRafale.filter((r) => r.created_at < lead.created_at || (r.created_at === lead.created_at && r.id <= lead.id)).length;
  if (rang > MAX_PAR_ARTISAN) { rendre(lead, 'refus', 'throttle'); continue; }
  // lib/plateformeConfig.ts:216-229 (decisionReponse) ; nbReponsesIA vaut 0 pour un premier message (route :319), prise_en_main est faux.
  const cfg = { ...DEFAUT, ...(reglages[lead.artisan_id] || {}) };
  const message = texte(lead.message);
  const verrou = cfg.mode_reponse === 'auto' && !PLANS_AUTO.includes(artisan.plan);
  const mode = verrou ? 'assistee' : cfg.mode_reponse;
  if (mode === 'manuelle') { rendre(lead, 'refus', 'manuelle'); continue; }
  const mot = motEscalade(cfg, message);
  if (mot) { rendre(lead, 'escalade', 'escalade', { mot }); continue; }
  if (mode === 'assistee') { rendre(lead, 'attend_artisan', verrou ? 'verrou_offre' : 'assistee'); continue; }
  const sujet = sujetEscalade([message], cfg.escalade_mots);
  if (sujet) { rendre(lead, 'escalade', 'escalade', { mot: sujet }); continue; }
  if (0 >= (cfg.limite_messages == null ? 8 : cfg.limite_messages)) { rendre(lead, 'refus', 'limite'); continue; }
  if (!dansLaPlage(cfg, new Date(lead.created_at))) { rendre(lead, 'refus', 'horaire'); continue; }
  rendre(lead, 'part_seul', 'auto');
}
return sortie;

// presti-reponse-seule : la place du MODÈLE. ÉPINGLÉ : ce nœud n'appelle rien, il rend une réponse d'exemple fixe pour chaque demande dont la
// décision est « part_seul » (rien pour les autres). Le jour où le workflow est publié, ce nœud est remplacé par le modèle (le prompt de
// lib/ai.ts:412-438 et le garde-fou de lib/ai/antiFabrication.ts : brief, « Avant la bascule »). La garde commune n'admet encore aucun nœud de
// modèle dans un workflow du chantier 4 (scripts/n8n-specs-qa.mjs, liste blanche de la famille c4) : voir le brief.
const REPONSE_EPINGLEE = 'Réponse exemple.';
return $input.all().map((i) => ({ json: { ...i.json, modele: 'epingle', texte_modele: i.json.decision === 'part_seul' ? REPONSE_EPINGLEE : null } }));

// presti-reponse-seule : ce qu'envoie le chemin codé quand la décision est « part seul » (app/api/leads/route.ts:473-509) — la réponse au
// prospect, au nom de l'artisan, avec la mention d'IA (lib/mentionAssistant.ts:14-17), puis l'avis « Nouveau lead » à l'artisan — et, pour
// un mot d'escalade, l'alerte à l'artisan (:383-392). Les plafonds de lib/email.ts que ce chemin passait en envoyant sont repris (:81-87).
// Code pur : rien n'est envoyé ici, rien n'est écrit. Copie figée contrôlée par scripts/reponse-seule-n8n-qa.mjs, cas par cas contre la
// vraie route. Les silences (manuelle, hors plage, limite) et le mode assisté sont des décisions sans courrier : leurs courriers relèvent
// de presti-accuse-reception et de la réponse proposée.
const MAX_PAR_DESTINATAIRE = 3;
const MAX_PAR_JOUR = 30;
const MAX_AVIS_PAR_JOUR = 50;
const EXPEDITEUR = 'contact@prestiapp.fr';
const ENTREPRISE = 'contact@prestiapp.fr';
const EST_COURRIEL = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;
const ADRESSE_SURE = /^[A-Za-z0-9._+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/;
const lire = (nom) => $(nom).all().map((i) => i.json).filter((x) => x && typeof x === 'object' && typeof x.id === 'string');
const ordre = (a, b) => (a.created_at < b.created_at ? -1 : a.created_at > b.created_at ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
const texte = (v) => (typeof v === 'string' ? v : '');
const sur = (v) => ADRESSE_SURE.test(texte(v).trim()) && !/\.invalid$/i.test(texte(v).trim());
const nettoyer = (v) => texte(v).replace(/[\r\n<>"]/g, '').trim().slice(0, 70) || 'Votre artisan';
const uneLigne = (v) => texte(v).replace(/[\r\n]+/g, ' ');
const actif = (prefs) => !prefs || typeof prefs !== 'object' || prefs.nouvelle_demande !== false;
const duJour = lire('Lire demandes du jour').sort(ordre);
const rangJour = {};
duJour.forEach((d, i) => { rangJour[d.id] = i + 1; });
const comptes = {};
lire('Lire comptes').forEach((c) => { comptes[c.id] = c; });
const demandes = {};
lire('Lire demandes').forEach((d) => { demandes[d.id] = d; });
const parAdresse = {};
lire('Lire doublons').filter((d) => typeof d.contact === 'string').sort(ordre).forEach((d) => {
  const k = d.contact.trim().toLowerCase();
  (parAdresse[k] = parAdresse[k] || []).push(d.id);
});
const sortie = [];
const decisions = $('Modele epingle').all().map((i) => i.json).filter((x) => x && x.courrier === 'decision').sort((a, b) => ordre(demandes[a.lead_id] || { created_at: '', id: a.lead_id }, demandes[b.lead_id] || { created_at: '', id: b.lead_id }));
for (const d of decisions) {
  const lead = demandes[d.lead_id];
  const artisan = lead ? comptes[lead.artisan_id] : null;
  if (!lead || !artisan) { sortie.push({ json: { courrier: 'ignore', lead_id: d.lead_id, raison: 'demande ou compte introuvable', simulation: true } }); continue; }
  const contact = texte(lead.contact).trim();
  const message = texte(lead.message);
  const nomProspect = texte(lead.nom_prospect);
  const nomArtisan = texte(artisan.nom);
  const estCourriel = EST_COURRIEL.test(contact);
  const avisDu = () => texte(artisan.email) && contact && actif(artisan.notifications) && sur(artisan.email) && rangJour[lead.id] <= MAX_AVIS_PAR_JOUR;
  const repondreA = ADRESSE_SURE.test(contact) && EST_COURRIEL.test(contact) ? contact : ENTREPRISE;
  const decision = { courrier: 'decision', lead_id: lead.id, decision: d.decision, motif: d.motif, mot: d.mot ?? null, envoi: null, avis: null, simulation: true };
  if (d.decision === 'escalade') {
    // app/api/leads/route.ts:383-392 : l'assistant se tait et l'artisan est alerté (le mot est dans le sujet : n8n lit le message).
    if (avisDu()) {
      decision.avis = 'alerte';
      sortie.push({ json: { courrier: 'avis', lead_id: lead.id, cle: 'avis:' + lead.id, simulation: true, a: texte(artisan.email).trim(), de: 'Presti <' + EXPEDITEUR + '>', repondre_a: repondreA,
        sujet: uneLigne('⚠️ Demande sensible (« ' + d.mot + ' ») — ' + (nomProspect || contact)),
        texte: 'Nouveau contact via votre page Presti — à vous de répondre.\n\nNom : ' + (nomProspect || 'non précisé') + '\nContact : ' + contact + '\nBesoin : ' + (message || 'non précisé') + '\n\nRépondez-lui depuis votre espace (Messages).' } });
    } else decision.avis = 'non_du';
  } else if (d.decision === 'part_seul') {
    const reponse = texte(d.texte_modele).trim();
    if (!reponse) { decision.envoi = 'aucune_reponse'; }
    else {
      const rang = (parAdresse[contact.toLowerCase()] || []).indexOf(lead.id) + 1;
      let partie = false;
      if (!contact) decision.envoi = 'sans_coordonnees';
      else if (!estCourriel) decision.envoi = 'pas_un_courriel';
      else if (/\.invalid$/i.test(contact)) { decision.envoi = 'adresse_de_test'; partie = true; }
      else if (!ADRESSE_SURE.test(contact)) decision.envoi = 'adresse_atypique';
      else if (!(rang >= 1 && rang <= MAX_PAR_DESTINATAIRE)) decision.envoi = 'plafond_destinataire';
      else if (!(rangJour[lead.id] <= MAX_PAR_JOUR)) decision.envoi = 'plafond_jour';
      else {
        decision.envoi = 'a_envoyer';
        partie = true;
        const nom = nomArtisan.replace(/[\r\n]+/g, ' ').trim().slice(0, 70);
        const corps = reponse;
        sortie.push({ json: { courrier: 'reponse', lead_id: lead.id, cle: 'reponse:' + lead.id, simulation: true,
          a: contact, de: nettoyer(nomArtisan.trim() || 'Votre artisan') + ' <' + EXPEDITEUR + '>', repondre_a: texte(artisan.email).trim(),
          sujet: uneLigne('Votre demande — ' + (nomArtisan.trim() || 'Votre artisan')),
          corps, de_artisan: nom ? ' de ' + nom : '',
          texte: corps + '\n\n—\nMessage rédigé et envoyé automatiquement par l’assistant' + (nom ? ' de ' + nom : '') + '.' } });
      }
      // app/api/leads/route.ts:493-509 : l'avis « Nouveau lead », avec la réponse et ce qu'il est advenu de l'e-mail au prospect.
      if (avisDu()) {
        decision.avis = 'nouveau_lead';
        const etat = !estCourriel ? 'Réponse automatique (prospect sans email — à rappeler)' : partie ? 'Réponse automatique envoyée au prospect par email' : 'Réponse automatique préparée, mais l’email au prospect N’EST PAS PARTI — recontactez-le vous-même';
        sortie.push({ json: { courrier: 'avis', lead_id: lead.id, cle: 'avis:' + lead.id, simulation: true, a: texte(artisan.email).trim(), de: 'Presti <' + EXPEDITEUR + '>', repondre_a: repondreA,
          sujet: uneLigne('Nouveau lead — ' + (nomProspect || contact)),
          texte: 'Nouveau contact via votre lien Presti.\n\nNom : ' + (nomProspect || 'non précisé') + '\nContact : ' + contact + '\nBesoin : ' + (message || 'non précisé') + '\n\n' + etat + ' :\n---\n' + reponse } });
      } else decision.avis = 'non_du';
    }
  }
  sortie.push({ json: decision });
}
return sortie;

parameters.text:
={{ $json.corps }}

—
Message rédigé et envoyé automatiquement par l’assistant{{ $json.de_artisan }}.
